  "inlineSchema": "// Configuración del cliente Prisma para SQLite (desarrollo) / PostgreSQL (producción)\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Tabla de marketplaces disponibles\nmodel Marketplace {\n  id                   String    @id @default(cuid())\n  name                 String    @unique\n  health_status        String    @default(\"unknown\") // healthy, unhealthy, unknown\n  last_health_check_at DateTime?\n  response_time_ms     Int?\n  created_at           DateTime  @default(now())\n  updated_at           DateTime  @updatedAt\n\n  // Relaciones\n  integrations Integration[]\n  orders       Order[]\n\n  @@map(\"marketplaces\")\n}\n\n// Tabla de integraciones por cliente\nmodel Integration {\n  id                    String  @id @default(cuid())\n  hermes_integration_id String // ID de la integración en Hermes (ej: \"2\", \"3\", \"10\") - viene de MarketplaceIntegration.id\n  cliente_name          String? // Nombre del cliente de Hermes (ej: \"Cheeky\", \"Markova\") - extraído del dominio\n  cliente_domain        String // Dominio del cliente de Hermes (ej: \"cheeky-hermes.com\") - REQUERIDO para constraint único\n  marketplace_id        String\n  estado                String  @default(\"active\") // active, inactive, suspended\n  ajustes_default       String? // Configuraciones por defecto para esta integración (JSON como string)\n\n  // Configuración de la instancia de Hermes para este cliente\n  hermes_api_url String? // URL de la instancia de Hermes del cliente (ej: http://cheeky-hermes.com)\n  hermes_token   String? // Token de autenticación para esta instancia de Hermes\n  hermes_enabled Boolean @default(true) // Si la integración con Hermes está habilitada\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  // Relaciones\n  marketplace Marketplace             @relation(fields: [marketplace_id], references: [id])\n  credentials IntegrationCredential[]\n  rules       IntegrationRule[]\n  orders      Order[]\n  sync_logs   SyncLog[]\n  sync_jobs   SyncJob[]\n\n  // Constraint único: hermes_integration_id es único POR CLIENTE (cliente_domain)\n  // Esto permite que:\n  // - Diferentes clientes puedan tener el mismo hermes_integration_id (ej: ambos tienen ID 2)\n  // - Un cliente puede tener múltiples integraciones del mismo marketplace\n  // - Dentro de un mismo cliente, no puede haber duplicados de hermes_integration_id\n  @@unique([cliente_domain, hermes_integration_id])\n  @@index([cliente_name]) // Índice para búsquedas rápidas por nombre\n  @@index([cliente_domain]) // Índice para búsquedas rápidas por dominio\n  @@map(\"integrations\")\n}\n\n// Tabla de credenciales encriptadas por integración\nmodel IntegrationCredential {\n  id                      String    @id @default(cuid())\n  integration_id          String\n  credentials_encrypted   String // JSON encriptado con tokens, secrets, etc.\n  access_token            String? // Token de acceso (encriptado) para acceso rápido\n  refresh_token           String? // Token de refresh OAuth2 (encriptado)\n  user_id                 String? // user_id de MercadoLibre (no encriptado, para búsquedas rápidas de webhooks)\n  expires_at              DateTime? // Timestamp de expiración del token\n  token_last_refreshed_at DateTime?\n  oauth_state             String? // Estado OAuth2 para validación de seguridad\n  created_at              DateTime  @default(now())\n  updated_at              DateTime  @updatedAt\n\n  // Relaciones\n  integration Integration @relation(fields: [integration_id], references: [id], onDelete: Cascade)\n\n  @@index([user_id]) // Índice para búsquedas rápidas por user_id (webhooks)\n  @@map(\"integration_credentials\")\n}\n\n// Tabla de reglas de negocio por integración\nmodel IntegrationRule {\n  id             String   @id @default(cuid())\n  integration_id String\n  rule_key       String // exclude_skus, add_tag_to_order, multiply_price, cap_stock, etc.\n  rule_json      String // Configuración específica de la regla (JSON como string)\n  enabled        Boolean  @default(true)\n  rule_type      String // inbound, outbound\n  priority       Int      @default(0) // Para ordenar aplicación de reglas\n  created_at     DateTime @default(now())\n  updated_at     DateTime @updatedAt\n\n  // Relaciones\n  integration Integration @relation(fields: [integration_id], references: [id], onDelete: Cascade)\n\n  @@unique([integration_id, rule_key, rule_type])\n  @@map(\"integration_rules\")\n}\n\n// Tabla de órdenes procesadas\nmodel Order {\n  id                 String    @id @default(cuid())\n  integration_id     String\n  marketplace_id     String\n  source_order_id    String // ID de la orden en el marketplace origen\n  payload_normalized String // Payload normalizado a formato interno (JSON como string)\n  status             String    @default(\"pending\") // pending, processed, blocked_by_rule, failed, sent_to_hermes\n  flag_reason        String? // Razón del bloqueo si status=blocked_by_rule\n  hermes_order_id    String? // ID asignado por Hermes OMS\n  retry_count        Int       @default(0)\n  last_error         String?\n  created_at         DateTime  @default(now())\n  processed_at       DateTime?\n  updated_at         DateTime  @updatedAt\n\n  // Relaciones\n  integration Integration @relation(fields: [integration_id], references: [id])\n  marketplace Marketplace @relation(fields: [marketplace_id], references: [id])\n\n  @@unique([marketplace_id, source_order_id])\n  @@index([integration_id, status])\n  @@index([created_at])\n  @@map(\"orders\")\n}\n\n// Tabla de logs de sincronización\nmodel SyncLog {\n  id             String   @id @default(cuid())\n  integration_id String\n  tipo           String // webhook_received, order_sent, catalog_sync, etc.\n  detalle        String // Detalles específicos del evento (JSON como string)\n  resultado      String // success, error, warning\n  response_data  String? // Respuesta del sistema externo (JSON como string)\n  created_at     DateTime @default(now())\n\n  // Relaciones\n  integration Integration @relation(fields: [integration_id], references: [id])\n\n  @@index([integration_id, tipo])\n  @@index([created_at])\n  @@map(\"sync_logs\")\n}\n\n// Tabla de trabajos de sincronización\nmodel SyncJob {\n  id             String    @id @default(cuid())\n  integration_id String\n  job_type       String // catalog_sync, stock_update, price_update, order_reconciliation\n  payload        String // Datos del trabajo (JSON como string)\n  status         String    @default(\"pending\") // pending, processing, completed, failed, cancelled\n  attempts       Int       @default(0)\n  max_attempts   Int       @default(3)\n  last_error     String?\n  scheduled_for  DateTime? // Para trabajos programados\n  started_at     DateTime?\n  completed_at   DateTime?\n  created_at     DateTime  @default(now())\n  updated_at     DateTime  @updatedAt\n\n  // Relaciones\n  integration Integration @relation(fields: [integration_id], references: [id])\n\n  @@index([integration_id, job_type])\n  @@index([status, scheduled_for])\n  @@index([created_at])\n  @@map(\"sync_jobs\")\n}\n",
  "inlineSchemaHash": "0f156a856627407dbcf3d3ea347656366437de7f51c01201796cccbdb245757d",
